// TH16 v1.00a bullet types used by this card.
// Copied from transcribe/th16/touhou-bullets.ecl (approved TH16_* aliases of
// identical TH18 type 0..43 slots, 2026-11-07). No engine content change.
const TH16_BALL: int = 416; // source etSprite type 4, base radius 4, colors 0..15
const TH16_RICE: int = 480; // source etSprite type 8, base radius 2.4, colors 0..15

// TH16 v1.00a Stage 1 -- MainSub02 / MainSub02b formation (th16_s1_w03)
// Source: st01.ecl.txt:1186-1216 (entry), 156-226 (GirlA02), 469-476 (GirlBlueA02),
//         509-589 (GirlC01), 966-973 (GirlRedA02).
// Source t=0 is MainSub02 entry, after the 120-frame opening buffer.
// GirlRedA02/GirlBlueA02 run GirlA02; GirlC01 mirrors itself when its spawn FINAL_X > 0.
// Ranks in scope: 0 (Easy) and 3 (Lunatic); source values for 1/2 are kept where given.

const TIME_LIMIT: int = 2324; // 120 opening + 2200 source budget + startup margin
const OPENING_BUFFER: int = 120;

const A02_COLOR: int = 6; // source etSprite(0, 4, 6)
const C01_COLOR: int = 6; // source etSprite(0, 8, 6)

// --- GirlA02_at: one aimed bullet, then A more; H/L only (source 1180-226) ---
async sub girl_a02_shot() {
    var rank: int = global(GVAR_RANK);
    var gap: int = 20;      // !H wait 20
    var spd: fx = 2fx;      // !H 2.0
    var delay: int = 30;    // one RAND draw, range follows rank
    if rank >= 3 {
        gap = 10;           // !LO wait 10
        spd = 3fx;          // !LO 3.0
        delay = delay + rand(30); // !LO: ($RAND % 30) + 30
    } else {
        delay = delay + rand(180); // !H/!E/!N: ($RAND % 180) + 30
    }
    wait(delay);
    // etAim(0,0) aimed fan with 1 way / 1 layer: angle = player direction.
    // etEx type 2 (ANIM) a=1: birth animation omitted, position -= 4*velocity kept.
    var back: fx = 4fx * spd;
    for k in 0..4 { // diffI($A,1,1,4,4): H/L = 4 shots
        var a: angle = aim_player();
        _ = fire(TH16_BALL, A02_COLOR, $self_x - back * cos(a), $self_y - back * sin(a),
                 spd, a, none, none);
        wait(gap);
    }
}

// --- GirlA02 (source 156-178) ---
async sub girl_a02() {
    set_invuln(65535);
    set_hurtbox(12fx); // setHurtbox(24,24): circle radius 24*0.5
    set_hitbox(8fx);   // setHitbox(16,16): circle radius 16*0.5
    move_vel(0, 90deg, 3fx, EASE_LINEAR); // moveVel(pi/2, 3.0)
    wait(30);
    if global(GVAR_RANK) >= 2 { // source !HL: @GirlA02_at() async;
        spawn girl_a02_shot();
    }
    move_vel(30, 0deg, 2fx, EASE_LINEAR); // moveVelTime(30, 0, 0.0, 2.0)
    wait(120);
    move_vel(30, 90deg, 2fx, EASE_LINEAR); // moveVelTime(30, 0, pi/2, 2.0)
    wait(30);
    move_vel(30, 180deg, 2fx, EASE_LINEAR); // moveVelTime(30, 0, pi, 2.0)
    wait(60);
    // moveVelTime(60, 0, -999999, 3.0): angle sentinel keeps pi, speed 2 -> 3.
    move_speed(60, 3fx, EASE_LINEAR);
    loop { wait(1000); } // GirlA02_372/GirlA02_392 wait loop
}

// --- GirlC01_at: fixed-direction fan, per-rank ways/layers/speed (source 535-589) ---
async sub girl_c01_shot() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var ways: int = 5;    // etCount param 1 = stack top = second block (!LO 5)
    var layers: int = 4;  // etCount param 2 = below top = first block (!LO 4)
    var spd0: fx = 3.6fx; // !LO 3.6
    var gap: int = 30;    // !LO wait 30
    var reps: int = 4;    // diffI($B,1,2,3,4) = !LO 4 rounds
    if rank == 0 {
        ways = 1; layers = 1; spd0 = 1.3fx; gap = 60; reps = 1;
    } else if rank == 1 {
        ways = 3; layers = 2; spd0 = 1.6fx; gap = 60; reps = 2;
    } else if rank == 2 {
        ways = 5; layers = 3; spd0 = 2.6fx; gap = 60; reps = 3;
    }
    for round in 0..reps {
        for q in 0..layers { // native order: layer outer, way inner
            var speed: fx = spd0;
            if layers > 1 {
                // etSpeed(s0,s1): v(q) = s0 + (s1-s0)*q/(layers-1), s1 = 1.0
                speed = spd0 + (1fx - spd0) * (q as fx) / ((layers - 1) as fx);
            }
            // etEx type 2 (ANIM) a=1: birth animation omitted, position -= 4*velocity kept.
            var back: fx = 4fx * speed;
            for i in 0..ways {
                // etAim(0,1) fixed fan: alpha + F(N,i); alpha = pi/2, delta = pi/4.
                var off: int = 0; // 45deg = 8192 BAM
                if ways > 1 {
                    off = ((i + 1) / 2) * 8192;
                    if ways % 2 == 0 { off = (i / 2) * 8192 + 4096; }
                    if i % 2 != 0 { off = -off; }
                }
                var a: angle = 90deg + (off as angle);
                _ = fire(TH16_RICE, C01_COLOR, $self_x - back * cos(a), $self_y - back * sin(a),
                         speed, a, none, none);
            }
        }
        wait(gap);
    }
}

// --- GirlC01 (source 509-533) ---
async sub girl_c01(mirror: int) {
    set_invuln(65535);
    set_hurtbox(16fx); // setHurtbox(32,32): circle radius 32*0.5
    set_hitbox(12fx);  // setHitbox(24,24): circle radius 24*0.5
    move_vel(0, 90deg, 2fx, EASE_LINEAR); // moveVel(pi/2, 2.0)
    // moveVelTime(80, 1, 1.3744467, 0.5); mode 1 = t^2.
    // moveSetMirror(1) mirrors x at the instruction write point: angle -> pi - angle.
    var turn: angle = 78.75deg; // 1.3744467 rad
    if mirror != 0 { turn = 180deg - turn; }
    move_vel(80, turn, 0.5fx, EASE_QUAD_IN);
    spawn girl_c01_shot();
    wait(60);
    loop { wait(1000); }
}

// --- MainSub02b (source 1202-1216): C01 schedule, returns at 650 frames ---
async sub main_sub02b() {
    _ = spawn_enemy(120fx, -24fx, 500, 0, 0, 0, girl_c01(1));
    wait(130);
    _ = spawn_enemy(-60fx, -24fx, 500, 0, 0, 0, girl_c01(0));
    wait(130);
    _ = spawn_enemy(60fx, -24fx, 500, 0, 0, 0, girl_c01(1));
    wait(130);
    _ = spawn_enemy(-120fx, -24fx, 500, 0, 0, 0, girl_c01(0));
    wait(130);
    _ = spawn_enemy(160fx, -24fx, 500, 0, 0, 0, girl_c01(1));
    _ = spawn_enemy(-160fx, -24fx, 500, 0, 0, 0, girl_c01(0));
    wait(130);
}

// --- MainSub02 (source 1186-1200): 13 rounds of Red + Blue, 30 frames per round ---
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn main_sub02b(); // source @MainSub02b() async;
    var a: int = 13;
    while a > 0 { // source runs the body 13 times (test before first body via $A--)
        _ = spawn_enemy(-120fx, -24fx, 100, 0, 0, 0, girl_a02); // GirlRedA02
        wait(15);
        _ = spawn_enemy(-120fx, -24fx, 100, 0, 0, 0, girl_a02); // GirlBlueA02
        wait(15);
        a = a - 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
